def is_positive_odd_or_negative_even(num: int) -> bool:
    # positive and odd
    if num > 0 and num % 2 != 0:
        return True
    # negative and even
    if num < 0 and num % 2 == 0:
        return True
    return False

def within_and_has_double_quotes(s: str) -> bool:
    # must have at least the two surrounding quotes
    if len(s) < 2:
        return False
    # must start and end with a double quote
    if not (s[0] == '"' and s[-1] == '"'):
        return False
    # at least one double quote strictly inside
    return '"' in s[1:-1]

def replace_middle(t: tuple, n: int) -> tuple:
    mid = len(t) // 2                 # index of the middle element
    return t[:mid] + (t[mid],) * n + t[mid + 1:]

def count_positives(lst: list) -> int:
    # keep only non-None values that are strictly positive
    return sum(1 for x in lst if x is not None and x > 0)
